// Reset synchroniser for a reset generated by a register in another
// clock domain (rtl-buddy-cdc#367).
//
// `a_rst_n` is a src_clk register (async reset from the port `rst_n`).
// Two dst_clk flops form the textbook async-assert / sync-deassert
// synchroniser for it: async reset `a_rst_n`, head D tied to 1, Q->D
// chain. The data flop uses the synchroniser's output as its async
// reset. Taking a foreign-domain async reset on their own reset pin is
// what the synchroniser flops are for, so RDC-001 must stay silent: the
// only reset crossing is the one being synchronised.
//
// Paired with `bad_reset_sync_foreign_reg` (single stage, backwards
// polarity, ordinary flop on the raw reset) and `good_reset_sync`
// (port-sourced reset).

module good_reset_sync_foreign_reg (
    input  logic src_clk,
    input  logic dst_clk,
    input  logic rst_n,
    input  logic d_in,
    output logic q_out
);

    logic a_rst_n;
    always_ff @(posedge src_clk or negedge rst_n) begin
        if (!rst_n) a_rst_n <= 1'b0;
        else        a_rst_n <= 1'b1;
    end

    logic s0, s1;
    always_ff @(posedge dst_clk or negedge a_rst_n) begin
        if (!a_rst_n) begin
            s0 <= 1'b0;
            s1 <= 1'b0;
        end else begin
            s0 <= 1'b1;
            s1 <= s0;
        end
    end

    always_ff @(posedge dst_clk or negedge s1) begin
        if (!s1) q_out <= 1'b0;
        else     q_out <= d_in;
    end

endmodule
